head.script:
scwin.screenId = "jldfil53000n";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_pubOfrSchdlAndCapMasterPage.get("total")) + "건 (" + String(dma_pubOfrSchdlAndCapMasterPage.get("currentPage")) + "/" + String(dma_pubOfrSchdlAndCapMasterPage.get("endListPage")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.initPageIndex
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initPageIndex = function () {
    /* sdd-asis-lifecycle:begin initPageIndex — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_pubofrSchdlReq').set('pageIndex', "1");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_openAdjReqWin();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil53000n.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_pageSize_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_pageSize_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_pageSize_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.initPageIndex();await scwin.searchList()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil53000n.slc_pageSize_onchange' }); }
};

/**
 * @event
 * @name scwin.grd_pubOfrSchdlAndCapMasterPageList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_pubOfrSchdlAndCapMasterPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pubOfrSchdlAndCapMasterPageList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_pubOfrSchdlAndCapMasterPageList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["step1DtlStat"] === '30') { if (typeof scwin.pubofrSchdl === 'function') { await scwin.pubofrSchdl(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.pubofrSchdl (열 작성중)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.pubofrSchdl'); } return; } return; } if (r["step1DtlStat"] === '') { if (typeof scwin.pubofrSchdl === 'function') { await scwin.pubofrSchdl(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.pubofrSchdl (열 미작성)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.pubofrSchdl'); } return; }
        if (r["step1DtlStat"] === '32') { if (typeof scwin.pubofrSchdl === 'function') { await scwin.pubofrSchdl(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.pubofrSchdl (열 제출완료)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.pubofrSchdl'); } return; }
        if (r["step1DtlStat"] === '33') { if (typeof scwin.pubofrSchdl === 'function') { await scwin.pubofrSchdl(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.pubofrSchdl (열 접수완료)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.pubofrSchdl'); } return; }
        if (r["step1DtlStat"] === '34') { if (typeof scwin.pubofrSchdl === 'function') { await scwin.pubofrSchdl(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.pubofrSchdl (열 수정요청)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.pubofrSchdl'); } return; }
        if (r["step1DtlStat"] === '35') { if (typeof scwin.pubofrSchdl === 'function') { await scwin.pubofrSchdl(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.pubofrSchdl (열 수정가능)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.pubofrSchdl'); } return; }
        if (r["step1DtlStat"] === '36') { if (typeof scwin.pubofrSchdl === 'function') { await scwin.pubofrSchdl(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.pubofrSchdl (열 수정불가)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.pubofrSchdl'); } return; }
        if (r["step1DtlStat"] === '37') { if (typeof scwin.pubofrSchdl === 'function') { await scwin.pubofrSchdl(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.pubofrSchdl (열 재작성)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.pubofrSchdl'); } return; }
        if (r["step2DtlStat"] === '') { if (typeof scwin.cap === 'function') { await scwin.cap(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.cap (열 미작성)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.cap'); } return; }
        if (r["step2DtlStat"] === '30') { if (typeof scwin.cap === 'function') { await scwin.cap(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.cap (열 작성중)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.cap'); } return; }
        if (r["step2DtlStat"] === '32') { if (typeof scwin.cap === 'function') { await scwin.cap(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.cap (열 제출완료)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.cap'); } return; }
        if (r["step2DtlStat"] === '33') { if (typeof scwin.cap === 'function') { await scwin.cap(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.cap (열 접수완료)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.cap'); } return; }
        if (r["step2DtlStat"] === '34') { if (typeof scwin.cap === 'function') { await scwin.cap(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.cap (열 수정요청)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.cap'); } return; }
        if (r["step2DtlStat"] === '35') { if (typeof scwin.cap === 'function') { await scwin.cap(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.cap (열 수정가능)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.cap'); } return; }
        if (r["step2DtlStat"] === '36') { if (typeof scwin.cap === 'function') { await scwin.cap(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.cap (열 수정불가)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.cap'); } return; }
        if (r["step2DtlStat"] === '37') { if (typeof scwin.cap === 'function') { await scwin.cap(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.cap (열 재작성)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.cap'); } return; }
        if (r["submitPossibleYn"] === 'Y') { if (typeof scwin.submit === 'function') { await scwin.submit(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.submit (열 제출)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.submit'); } return; }
        if (r["step1DtlStat"] === '35' || r["step2DtlStat"] === '35') { if (typeof scwin.submit === 'function') { await scwin.submit(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.submit (열 제출)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.submit'); } return; }
        if (r["step1DtlStat"] === '34' || r["step2DtlStat"] === '34') { if (typeof scwin.openAdjReqPop === 'function') { scwin.openAdjReqPop(r["bzProcsNo"], "130"); } else { console.error('[sdd] 행 동작 미정의: scwin.openAdjReqPop (열 수정요청)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openAdjReqPop'); } return; }
        if (r["step1DtlStat"] === '35' || r["step2DtlStat"] === '35') { if (typeof scwin.openAdjReqPop === 'function') { scwin.openAdjReqPop(r["bzProcsNo"], "130"); } else { console.error('[sdd] 행 동작 미정의: scwin.openAdjReqPop (열 수정요청)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openAdjReqPop'); } return; }
        if (r["recvCompleteYn"] === 'Y') { if (typeof scwin.openAdjReqPop === 'function') { scwin.openAdjReqPop(r["bzProcsNo"], "130"); } else { console.error('[sdd] 행 동작 미정의: scwin.openAdjReqPop (열 수정요청)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openAdjReqPop'); } return; }
    } catch (e) {
