/**
 * @method
 * @name scwin.grd_pubOfrSchdlAndCapMasterPageList_fmt_column7
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_pubOfrSchdlAndCapMasterPageList_fmt_column7 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pubOfrSchdlAndCapMasterPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "step1DtlStat") ?? '') : '');
        if (v === '') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "미작성" + '</a>'; }
        if (v === '30') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "작성중" + '</a>'; }
        if (v === '32') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "제출완료" + '</a>'; }
        if (v === '33') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "접수완료" + '</a>'; }
        if (v === '34') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "수정요청" + '</a>'; }
        if (v === '35') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "수정가능" + '</a>'; }
        if (v === '36') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "수정불가" + '</a>'; }
        if (v === '37') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "재작성" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pubOfrSchdlAndCapMasterPageList.column7" }); return String(data ?? ''); }
};

